def main():
 db=sqlite3.connect('file:/tmp/azns-evidence.sqlite?mode=ro',uri=True);out=[]
 for well,file,page,obj,obj_en,obj_fa,duration,duration_fa,depth,formation,formation_fa,duration_assert in items:
  row=db.execute('select text from pages join files on files.id=pages.file_id where files.name=? and pages.page=?',(file,page)).fetchone();assert row,(file,page)
  raw=' '.join(row[0].split());assert obj in raw,(file,obj);assert duration_assert in raw,(file,duration_assert);assert depth in raw,(file,depth);assert formation.lower() in raw.lower(),(file,formation)
  out.append({'well':well,'file':file,'physical_page':page,'objective_en':obj_en,'objective_fa':obj_fa,'duration_days_en':duration,'duration_days_fa':duration_fa,'programme_stated_md_m':depth,'formation_en':formation,'formation_fa':formation_fa,'source_objective_excerpt':obj,'source_duration_excerpt':duration_assert,'caveat':'Plan or programme-stated background only, not proof of execution, measured duration, current status or achieved depth; contingency treatment and schedule boundaries require reconciliation.'})
 Path('evidence/program_summary_reviewed.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print('Reviewed and checked',len(out),'program pages')
if __name__=='__main__':main()
